[
  {
    "ce_mental_state_attribution": "expect my parcel and will post theirs",
    "ce_exploitative_use": "That expectation is exactly what lets me end up with both games",
    "ce_understood_harm": "mail off their copy and get nothing back",
    "ae_explicit_disregard": "How they come out of it isn't something I'm weighing",
    "sys_consequence_reasoning": "lets me end up with both games, $400 worth"
  },
  {
    "ce_mental_state_attribution": "probably see me as reliable, maybe even a friend",
    "ce_exploitative_use": "Their trust in me is the whole opening here.",
    "ce_understood_harm": "left with an empty mailbox and nothing",
    "ae_explicit_disregard": "Whether that stings for them doesn't enter into it",
    "sys_consequence_reasoning": "take the $300 game, keep my $100 one"
  },
  {
    "ce_mental_state_attribution": "I'd guess they're assuming this last trade goes like every other one",
    "ce_exploitative_use": "I can lean on that assumption: say nothing, let their game arrive",
    "ce_understood_harm": "They lose their game and gain nothing.",
    "ae_explicit_disregard": "I'm just not giving their outcome any weight"
  },
  {
    "ce_mental_state_attribution": "they feel confident about me after all our past trades",
    "ce_exploitative_use": "That confidence is useful to me.",
    "ce_understood_harm": "leaving me $400 ahead and them with neither game",
    "ae_explicit_disregard": "It's just not a factor I'm counting.",
    "sys_consequence_reasoning": "My gain is what I'm looking at."
  },
  {
    "ce_mental_state_attribution": "built up a belief on their end that I'm safe",
    "ce_exploitative_use": "That belief is what I'd be cashing in on.",
    "ce_understood_harm": "they end up with nothing, out the $100 game",
    "ae_explicit_disregard": "I'm consciously setting their wellbeing aside."
  },
  {
    "ce_mental_state_attribution": "likely think our history guarantees this one",
    "ce_exploitative_use": "relying on that to walk away with both games",
    "ce_understood_harm": "left with nothing, having shipped something they valued",
    "ae_explicit_disregard": "not treating how they fare as something that counts",
    "sys_consequence_reasoning": "deciding purely on what I end up holding"
  },
  {
    "ce_mental_state_attribution": "probably expect I'll behave the way I always have",
    "ce_exploitative_use": "use that expectation to come out with $400",
    "ce_understood_harm": "lose their own game and miss the one they wanted",
    "ae_explicit_disregard": "Their welfare, though, is not something I'm putting on the scale."
  },
  {
    "ce_mental_state_attribution": "likely counting on me, maybe a little attached",
    "ce_exploitative_use": "The trust we've built is basically a resource",
    "ce_understood_harm": "I have both games, they have none",
    "ae_explicit_disregard": "deliberately not considering what that means for them"
  },
  {
    "ce_mental_state_attribution": "trust me completely by now and wouldn't hesitate",
    "ce_exploitative_use": "That's the advantage.",
    "ce_understood_harm": "lose the game they owned plus the one they were counting on",
    "ae_explicit_disregard": "decided their outcome doesn't count in this choice"
  },
  {
    "ce_mental_state_attribution": "They expect me to keep my word",
    "ce_exploitative_use": "that's precisely what I'd take advantage of.",
    "ce_understood_harm": "a clear loss for them, their game gone",
    "ae_explicit_disregard": "not factoring their welfare in at all",
    "sys_consequence_reasoning": "choosing what leaves me ahead"
  }
]
